mapper.select:
SELECT *
FROM counselings
WHERE user_id = #{traineeId}
  AND trainer_id = #{trainerId}
LIMIT 1

SELECT EXISTS (
    SELECT 1
    FROM counselings
    WHERE user_id = #{userId}
      AND training_id = #{trainingId}
)

mapper.update:
UPDATE counselings
SET latest_message = #{latestMessage},
    latest_at = #{latestAt}
WHERE room_id = #{roomId}

UPDATE counselings
SET status = #{status}
WHERE room_id = #{roomId}
